const caseSteps=[['Làm rõ vấn đề','Viết problem statement, phân biệt triệu chứng và nguyên nhân. Nêu mục tiêu và phạm vi.'],['Hỏi để xác nhận','Đặt ít nhất 5 câu hỏi khai thác. Phân biệt dữ kiện đã biết và giả định cần kiểm chứng.'],['Stakeholder & giao tiếp','Xác định người dùng, người quyết định và các bên bị ảnh hưởng. Đề xuất cách xác nhận yêu cầu.'],['Yêu cầu & ưu tiên','Liệt kê yêu cầu chức năng, phi chức năng và business rule; ưu tiên Must / Should / Could.'],['Giải pháp & nghiệm thu','So sánh ít nhất 2 phương án, mô tả luồng chính và ngoại lệ, viết tiêu chí chấp nhận kiểm chứng được.'],['Rủi ro & đánh đổi','Nêu rủi ro, khả năng xảy ra, tác động, biện pháp giảm thiểu và người chịu trách nhiệm.'],['Đo lường kết quả','Định nghĩa KPI: công thức, baseline, mục tiêu đề xuất, cửa sổ đo và chỉ số bảo vệ.']];
const caseStudies=[
{id:'retail',title:'Đơn đã thanh toán, kho lại hết hàng',level:'Junior',domain:'Bán lẻ',skill:'Yêu cầu & quy trình',minutes:40,accent:'#7c68d7',icon:'case',summary:'Giảm đơn hủy do tồn kho lệch giữa cửa hàng và kênh online.',context:'Một chuỗi 12 cửa hàng dùng chung website bán hàng. Khách thanh toán thành công nhưng sau đó nhận cuộc gọi báo hết hàng. Giám đốc đề nghị “xây app kho mới trong 6 tuần”. Bạn là BA cần làm rõ vấn đề trước khi chốt giải pháp.',facts:['Tháng gần nhất: 10.000 đơn online; 600 đơn hủy vì hết hàng sau thanh toán.','Tồn kho website đồng bộ từ cửa hàng mỗi 30 phút. Có bán trực tiếp tại quầy trong khoảng chờ.','Mỗi đơn hủy cần trung bình 12 phút CSKH xử lý; đây là số trung bình theo mẫu đo hiện tại.','Đội triển khai gồm 2 developer, 1 QA; thời hạn MVP 6 tuần. Chưa có số liệu tách theo SKU/cửa hàng.'],twist:'Quản lý cửa hàng không muốn khóa tồn kho quá lâu vì sợ mất cơ hội bán trực tiếp.',hint:'Đừng kết luận “đồng bộ chậm” là nguyên nhân duy nhất. Hãy kiểm tra đồng thời: race condition, tồn thực tế, giữ chỗ, đơn treo và sai lệch vận hành.',models:[
'Vấn đề: 6% đơn online bị hủy do hết hàng sau thanh toán (600/10.000). Đây là baseline, chưa chứng minh nguyên nhân. Mục tiêu đề xuất: giảm tỷ lệ này xuống dưới 2% trong 4 tuần sau pilot; cần sponsor chấp thuận. MVP tập trung đặt hàng và giữ tồn, chưa thay toàn bộ phần mềm kho.',
'Đơn hủy tập trung ở SKU/cửa hàng nào? Tồn khả dụng được tính thế nào? Có giữ chỗ trước thanh toán không? Đơn chờ thanh toán hết hạn lúc nào? Quầy và online trừ tồn theo cơ chế nào? Hàng trả về được cộng lại khi nào? Yêu cầu log để kiểm tra giả thuyết trước khi kết luận.',
'Khách hàng và thu ngân là người dùng; quản lý kho chịu trách nhiệm tồn; CSKH xử lý sự cố; tài chính xác nhận hoàn tiền; sponsor quyết định mục tiêu; IT đánh giá tích hợp. Quan sát một ca bán hàng, phỏng vấn từng nhóm và workshop để thống nhất quy tắc giữ chỗ.',
'Must: tồn khả dụng, giữ chỗ có thời hạn cấu hình, xác nhận thanh toán, giải phóng giữ chỗ khi hết hạn và chống trừ tồn lặp. Should: cảnh báo sai lệch và báo cáo hủy. Could: dự báo tồn. NFR: cập nhật nhất quán tại điểm xác nhận, có log truy vết; SLA độ trễ phải thống nhất sau đo thử.',
'So sánh tăng tần suất đồng bộ với giữ tồn tập trung. Phương án đầu ít thay đổi nhưng còn khoảng đua; phương án sau cần tích hợp tại quầy. Pilot nhóm SKU rủi ro cao. AC: với tồn khả dụng 1 và hai yêu cầu đồng thời, tối đa một yêu cầu giữ chỗ thành công. Callback thanh toán lặp không trừ tồn thêm.',
'Giữ tồn làm giảm hàng bán tại quầy: thống nhất TTL và theo dõi đơn treo. Mạng mất làm lệch trạng thái: quy trình retry, đối soát và thao tác hỗ trợ có audit log. Webhook chậm: trạng thái chờ xác minh, không khẳng định thanh toán thất bại chỉ vì timeout.',
'KPI chính = đơn hủy do thiếu tồn sau thanh toán / tổng đơn đã thanh toán, đo theo tuần và so cùng cửa hàng/SKU. Mục tiêu dưới 2% là đề xuất cần pilot. Guardrail: chuyển đổi thanh toán, tồn bị giữ quá hạn, thời gian hoàn tiền. Chỉ tính lợi ích xử lý: 600 × 12 = 7.200 phút/tháng, chưa phải lợi nhuận thu hồi.'
]},
{id:'appointment',title:'Lịch còn trống nhưng khách phải chờ',level:'Junior',domain:'Dịch vụ',skill:'Stakeholder & nghiệp vụ',minutes:35,accent:'#4b9d91',icon:'calendar',summary:'Thiết kế luồng đặt lịch cho một chuỗi trung tâm dịch vụ.',context:'Ba trung tâm chăm sóc xe nhận lịch qua điện thoại và biểu mẫu. Khách đến đúng giờ vẫn phải chờ vì một số dịch vụ cần đồng thời kỹ thuật viên và cầu nâng. Chủ doanh nghiệp muốn “cho khách tự chọn bất kỳ giờ nào còn trống”.',facts:['Mỗi ngày có 120 lượt đặt; 24 lượt chờ hơn 20 phút.','Mỗi trung tâm có 2 cầu nâng; thời lượng dịch vụ từ 30–90 phút.','8% lịch không đến; chưa tách khách hủy trước với khách no-show.','Lịch kỹ thuật viên và tài nguyên đang ghi ở hai bảng khác nhau.'],twist:'Trưởng trung tâm muốn tiếp tục nhận khách vãng lai dù lịch online đã gần đầy.',hint:'Một slot trống trên lịch không đồng nghĩa có đủ toàn bộ tài nguyên. Làm rõ tổ hợp dịch vụ, thời gian đệm và ai được override.',models:[
'Vấn đề là đặt vượt năng lực hoặc phân bổ không phù hợp, chưa chắc chỉ do thiếu công cụ. Baseline: 24/120 = 20% lượt chờ hơn 20 phút. Mục tiêu đề xuất giảm xuống 10% trong pilot. Phạm vi: một trung tâm, một nhóm dịch vụ; không tối ưu toàn bộ chuỗi ngay.',
'Thời lượng thực tế biến động ra sao? Một kỹ thuật viên có phục vụ nhiều xe cùng lúc không? Dịch vụ nào cần cầu nâng? Cần bao nhiêu phút đệm? Khách đến muộn được xử lý thế nào? Override phải có ai duyệt? Định nghĩa riêng hủy trước, đến muộn và no-show.',
'Khách đặt lịch, lễ tân, kỹ thuật viên, trưởng trung tâm và điều phối là stakeholder chính. Quan sát luồng tiếp nhận; workshop kiểm tra lịch mẫu có xung đột. Trưởng trung tâm xác nhận quy tắc vận hành, khách thử prototype để kiểm tra cách trình bày slot.',
'Must: kiểm tra đồng thời tài nguyên và kỹ năng, chặn đặt trùng, đổi/hủy lịch và thời gian đệm. Should: nhắc lịch và waitlist. Could: gợi ý gói dịch vụ. Rule: chỉ hiển thị slot nếu đủ tài nguyên trong toàn bộ khoảng phục vụ. NFR: bảo vệ dữ liệu liên hệ, giới hạn quyền xem lịch.',
'So sánh nhận yêu cầu chờ xác nhận với xác nhận slot ngay theo năng lực. MVP có thể dùng phương án đầu nếu chưa tích hợp lịch. AC cho phương án thứ hai: khi hai người chọn slot có một cầu nâng còn lại, chỉ một lịch được xác nhận. Khi đổi lịch thất bại, lịch gốc vẫn được giữ.',
'Ước lượng thời lượng sai: lưu thời gian thực tế để hiệu chỉnh. Khách vãng lai làm vỡ lịch: dành buffer được phê duyệt và chỉ cho trưởng ca override có lý do. SMS lỗi: retry và hiện trạng thái gửi; không dùng “đã gửi SMS” làm bằng chứng khách đã đọc.',
'KPI = số lượt bắt đầu muộn hơn giờ hẹn trên 20 phút / tổng lượt đã đến có đặt lịch. Baseline cần tính lại đúng mẫu số vì dữ kiện ban đầu tính trên lượt đặt. Theo dõi công suất tài nguyên, no-show, mức chờ khách vãng lai và tỷ lệ đổi/hủy để tránh tối ưu một phía.'
]},
{id:'approval',title:'Một đề nghị mua sắm, năm lần chuyển tay',level:'Mid',domain:'Nội bộ',skill:'BPMN & quy tắc',minutes:50,accent:'#d5964a',icon:'flow',summary:'Thiết kế quy trình phê duyệt có phân quyền và ngoại lệ rõ ràng.',context:'Doanh nghiệp nhận đề nghị mua sắm bằng email. Người yêu cầu không biết hồ sơ đang ở đâu; lãnh đạo muốn “mọi khoản đều phải qua CFO”. Bạn cần đề xuất quy trình vừa kiểm soát vừa tránh tắc nghẽn.',facts:['300 đề nghị/tháng; trung vị xử lý 5 ngày làm việc.','25% hồ sơ bị trả lại ít nhất một lần vì thiếu thông tin.','Quy định nội bộ giả lập: dưới 10 triệu quản lý duyệt; 10–100 triệu thêm tài chính; trên 100 triệu thêm CFO.','Có mua khẩn cấp, người duyệt nghỉ phép và đề nghị vượt ngân sách.'],twist:'Một nhân viên tách khoản 120 triệu thành hai đề nghị 60 triệu để né cấp duyệt cao hơn.',hint:'Tách business rule về thẩm quyền khỏi sơ đồ luồng. Đừng bỏ qua rút hồ sơ, trả lại, sửa sau duyệt và ủy quyền.',models:[
'Vấn đề có thể gồm thiếu chuẩn đầu vào, thiếu trạng thái và hàng chờ duyệt. Mục tiêu đề xuất: trung vị 3 ngày và giảm hồ sơ trả lại xuống dưới 10% sau pilot. Chưa mặc định ép CFO duyệt mọi khoản vì điều đó có thể tăng thời gian chờ.',
'Ai sở hữu chính sách hạn mức? Ngưỡng có bao gồm thuế? Tỷ giá được chốt thời điểm nào? Trả lại khác từ chối thế nào? Sửa số tiền sau duyệt có reset luồng không? Ủy quyền được giới hạn đến đâu? Ai xử lý khẩn cấp và vượt ngân sách?',
'Người yêu cầu, quản lý, tài chính, mua hàng, CFO và kiểm soát nội bộ. Tài chính xác nhận bảng quyết định; CFO duyệt chính sách; IT quản lý quyền. Tổ chức walkthrough với một hồ sơ bình thường và các ngoại lệ để thống nhất mô hình To-be.',
'Must: biểu mẫu bắt buộc, định tuyến theo hạn mức, trạng thái, audit trail, ủy quyền và phê duyệt lại khi trường trọng yếu đổi. Should: nhắc hạn và theo dõi SLA. Rule chống tách đơn cần được chính sách nội bộ xác nhận: không tự gộp chỉ dựa trên người gửi hoặc ngày gửi.',
'So sánh biểu mẫu chuẩn kèm workflow nhẹ với hệ thống procurement đầy đủ. MVP chọn workflow nhẹ nếu đáp ứng quyền và audit. Luồng: Nháp → Gửi → Kiểm tra → Duyệt theo bảng quyết định → Mua hàng. AC: đúng 10 triệu phải vào nhánh tài chính; đúng 100 triệu vẫn thuộc nhánh 10–100 triệu theo quy tắc đề bài.',
'Người yêu cầu tự duyệt qua vai trò khác: kiểm tra phân tách nhiệm vụ. Người duyệt nghỉ phép: ủy quyền có ngày hiệu lực và không vượt thẩm quyền. Hồ sơ sửa sau duyệt: lưu phiên bản và thu hồi duyệt bị ảnh hưởng. Khẩn cấp cần ngoại lệ có audit, không bypass âm thầm.',
'Đo lead time từ gửi đủ hồ sơ đến quyết định cuối; báo median và P90, không chỉ trung bình. Tỷ lệ trả lại = hồ sơ trả lại ít nhất một lần / hồ sơ gửi trong cohort. Guardrail: vi phạm thẩm quyền, chi vượt ngân sách và tỷ lệ ngoại lệ; theo dõi theo nhóm hạn mức.'
]},
{id:'payments',title:'Timeout thanh toán có phải thất bại?',level:'Mid',domain:'Thương mại điện tử',skill:'API & dữ liệu',minutes:55,accent:'#568cae',icon:'data',summary:'Phân tích trạng thái giao dịch, callback trễ và đối soát.',context:'Ứng dụng bán vé gọi cổng thanh toán. Khi API timeout, app hiện “thanh toán thất bại” và khách bấm lại. Một số khách bị trừ tiền hai lần hoặc có tiền nhưng chưa có vé. Bạn cần làm rõ yêu cầu cho luồng bất đồng bộ.',facts:['20.000 lượt thanh toán/tuần; 2% lượt gọi timeout.','Một phần timeout vẫn được cổng xử lý thành công; chưa biết chính xác tỷ lệ.','Callback có thể đến trễ hoặc lặp; có trường hợp thứ tự sự kiện đảo.','Vé giữ chỗ 10 phút; callback có thể đến sau khi giữ chỗ hết hạn.'],twist:'Cổng báo thành công sau 12 phút nhưng ghế đã được bán cho khách khác.',hint:'Đừng suy diễn timeout thành thất bại. Tách đơn hàng, payment attempt và giao dịch; xác nhận khả năng idempotency thực tế của cổng.',models:[
'Cần tránh thu tiền lặp và thiếu quyền lợi sau thanh toán, không chỉ giảm lỗi hiển thị. Xác định tỷ lệ bị trừ lặp và thanh toán thành công chưa cấp vé làm baseline. Phạm vi gồm trạng thái chờ xác minh, idempotency, callback và đối soát; không hứa cấp lại ghế khi tài nguyên đã hết.',
'Cổng hỗ trợ khóa idempotency ở bước nào và giữ bao lâu? API tra cứu trạng thái có authoritative không? Callback được xác thực ra sao? Cơ chế retry và thứ tự sự kiện thế nào? Một đơn được có bao nhiêu attempt? Sau hết hạn giữ ghế, ai chịu trách nhiệm hoàn tiền?',
'Khách, CSKH, tài chính, đơn vị thanh toán, nhóm booking và kỹ thuật. Tài chính xác nhận trạng thái tiền và hoàn; booking xác nhận giữ ghế; provider xác nhận hợp đồng API. Workshop theo timeline sự kiện để thống nhất trạng thái thay vì chỉ bàn màn hình.',
'Must: định danh đơn/attempt/giao dịch; khóa idempotency ổn định cho cùng thao tác; callback xác thực và xử lý lặp; trạng thái Pending/Unknown; tra cứu và đối soát. NFR: không lưu dữ liệu thanh toán vượt nhu cầu, log phải che thông tin nhạy cảm. Retry có kiểm soát theo khả năng provider.',
'So sánh xử lý chỉ bằng callback với callback kết hợp tra cứu/đối soát. Chọn phương án sau khi cổng hỗ trợ. AC: callback thành công lặp ba lần vẫn chỉ cấp một vé; timeout hiển thị “đang xác minh”; callback sau hết giữ chỗ chuyển vào xử lý ngoại lệ/hoàn tiền, không tự tạo ghế mới.',
'Sự kiện đảo thứ tự: bảng chuyển trạng thái cho phép/không cho phép rõ ràng. Xử lý tranh chấp tại hai worker: cập nhật có kiểm soát đồng thời. Hoàn tiền thất bại: trạng thái riêng, retry và escalation. Khóa idempotency không được cổng hỗ trợ thì cần biện pháp khác, không khẳng định phía app đủ ngăn mọi lần trừ lặp.',
'Theo dõi tỷ lệ giao dịch trừ tiền lặp thực sự, thời gian từ thành công đến cấp vé, tuổi các giao dịch Pending và lệch đối soát. 2% timeout = 400 lượt/tuần, không đồng nghĩa 400 giao dịch thất bại. Guardrail: tỷ lệ thanh toán thành công và thời gian hoàn tiền.'
]},
{id:'reporting',title:'Hai dashboard, hai con số doanh thu',level:'Mid',domain:'Dữ liệu',skill:'SQL & KPI',minutes:45,accent:'#5b9d82',icon:'target',summary:'Thống nhất định nghĩa chỉ số trước khi sửa dashboard.',context:'Kinh doanh báo doanh thu tháng là 5 tỷ, tài chính báo 4,6 tỷ. CEO yêu cầu BA tìm “dashboard đúng”. Hai đội đều cho rằng truy vấn của mình chính xác.',facts:['Báo cáo kinh doanh tính theo ngày tạo đơn và tổng giá trước giảm giá.','Báo cáo tài chính tính theo ngày thanh toán và sau giảm giá; chưa rõ xử lý hoàn tiền.','Có dữ liệu đơn, dòng hàng, thanh toán, hoàn tiền; một đơn có nhiều lần thanh toán.','Pipeline một đội chạy UTC, đội còn lại hiển thị theo Asia/Saigon.'],twist:'JOIN đơn hàng với cả dòng hàng và payment làm nhân bản doanh thu trên đơn trả nhiều lần.',hint:'Grain của bảng và thời điểm ghi nhận là hai câu hỏi đầu tiên. Chênh lệch không có nghĩa một đội sai; có thể họ đang đo hai chỉ số khác nhau.',models:[
'Chưa kết luận hệ thống sai vì hai báo cáo dùng khái niệm khác nhau. Cần bảng đối soát chênh lệch theo định nghĩa và thống nhất metric catalog. Không tự coi chỉ số quản trị là doanh thu kế toán; định nghĩa kế toán phải được người có trách nhiệm xác nhận.',
'Chỉ số phục vụ quyết định nào? Ghi nhận theo sự kiện gì? Giá gồm thuế không? Voucher ai tài trợ? Hoàn một phần xử lý tháng nào? Múi giờ và cutoff là gì? Tỷ giá theo thời điểm nào? Loại đơn test/hủy ra sao? Chốt grain của mỗi phép tổng hợp.',
'CEO quyết định nhu cầu quản trị; kinh doanh và tài chính là chủ định nghĩa; data engineer xác nhận lineage; QA xác nhận kết quả mẫu. Workshop một tập đơn đại diện, ghi rõ thuật ngữ gross booking, tiền thu và doanh thu ghi nhận nếu phù hợp chính sách.',
'Must: metric catalog có owner, công thức, grain, thời gian, timezone, filter và phiên bản; truy vấn đối soát đến đơn nguồn. Should: test dữ liệu tự động và freshness indicator. NFR: quyền truy cập phù hợp. Thay đổi định nghĩa phải có ngày hiệu lực và cách so sánh lịch sử.',
'So sánh sửa một dashboard với metric layer dùng chung. Trước mắt làm bảng reconciliation rồi thống nhất layer. Gợi ý truy vấn: tổng hợp payment theo order_id và dòng hàng theo order_id riêng, sau đó join các kết quả cùng grain. AC: đơn 2 dòng × 2 payment không bị tính doanh thu bốn lần; đơn sát mốc tháng dùng cùng timezone.',
'Lịch sử mất khả năng so sánh khi đổi công thức: version metric và backfill được duyệt. Dữ liệu late-arriving: cửa sổ cập nhật và nhãn số tạm tính. Sai quyền làm lộ dữ liệu: phân quyền theo nhu cầu. Không sửa trực tiếp dữ liệu nguồn chỉ để hai báo cáo khớp.',
'Đo tỷ lệ chênh lệch còn chưa giải thích sau khi áp cùng định nghĩa, coverage test của metric quan trọng và độ trễ cập nhật. 5 tỷ − 4,6 tỷ = 0,4 tỷ là khoảng chênh ban đầu, không mặc định là thất thoát. Mục tiêu quản trị: mọi phần chênh có lý do và owner xác nhận.'
]},
{id:'ai-support',title:'Trợ lý AI trả lời nhanh nhưng có đáng tin?',level:'Senior',domain:'AI & sản phẩm',skill:'Đánh giá giải pháp',minutes:60,accent:'#b079a9',icon:'spark',summary:'Thiết kế pilot trợ lý CSKH với tiêu chí chất lượng và điểm chuyển người.',context:'Đội CSKH muốn dùng AI để giảm thời gian trả lời. Nhà cung cấp demo rất tốt trên 10 câu mẫu. Sponsor muốn cho AI tự trả lời mọi khách hàng ngay tháng tới. Bạn cần đề xuất cách đánh giá và giới hạn pilot.',facts:['5.000 ticket/tuần; thời gian xử lý trung bình 8 phút.','Kho tri thức có bài hết hiệu lực và hai chính sách đổi trả khác phiên bản.','Ticket có thể chứa thông tin liên hệ và mã đơn cá nhân.','Chưa có bộ đánh giá độc lập; 10 câu demo không đại diện toàn bộ ticket.'],twist:'Một câu trả lời đúng về văn phong nhưng áp dụng nhầm chính sách đổi trả cho thị trường khác.',hint:'Phân biệt tăng tốc soạn nháp và tự động quyết định. Chỉ số containment cao không đủ chứng minh chất lượng. Tách tập test với tập dùng chỉnh hệ thống.',models:[
'Nhu cầu là giảm công sức mà vẫn giữ chất lượng và bảo vệ dữ liệu. Chưa có bằng chứng demo 10 câu đủ cho triển khai rộng. Pilot đề xuất: AI soạn nháp cho một nhóm ticket rủi ro thấp, nhân viên duyệt trước khi gửi; phạm vi loại trừ hoàn tiền và ngoại lệ cần thẩm quyền.',
'Nhóm ticket nào chiếm nhiều thời gian? Sai sót nào gây tác động lớn? Nguồn tri thức ai duyệt? Chính sách có version/thị trường không? Dữ liệu nào được gửi nhà cung cấp? Điều kiện lưu giữ là gì? Nhân viên có quyền bác bỏ đề xuất? Ai quyết định dừng pilot?',
'CSKH, người quản lý tri thức, product owner, bảo mật, pháp chế nội bộ theo nhu cầu và đại diện khách hàng. Không đưa lời khuyên pháp lý giả định; yêu cầu chủ trách nhiệm xác nhận điều kiện dữ liệu. Chấm đôi một phần tập test để kiểm tra mức nhất quán đánh giá của con người.',
'Must: nguồn tri thức được duyệt và gắn hiệu lực, dẫn nguồn, chuyển người khi không có căn cứ, che dữ liệu và ghi nhận sửa/bác bỏ. Should: phản hồi nhân viên và phân tích lỗi. NFR: quyền truy cập, độ trễ, khả năng theo dõi và rollback. Không dùng điểm tự tin tự báo của mô hình như bảo chứng đúng.',
'So sánh tìm kiếm FAQ cải tiến với AI soạn nháp có truy xuất nguồn. Đánh giá trên tập ticket ẩn danh có phân tầng và tách khỏi tập tối ưu. AC: chính sách hết hiệu lực không được chọn; thiếu dữ kiện thị trường thì yêu cầu làm rõ hoặc chuyển người; nhân viên có thể sửa và từ chối trước khi gửi.',
'Hallucination hoặc sai phiên bản: kiểm soát nguồn, kiểm tra định kỳ và review. Prompt injection từ nội dung ticket: giới hạn quyền công cụ và coi ticket là dữ liệu không tin cậy. Rò rỉ dữ liệu: giảm dữ liệu gửi đi và xác nhận cấu hình lưu giữ. Có nút tắt, owner xử lý sự cố và quy trình quay lại thủ công.',
'Đo thời gian xử lý thực tế gồm cả review, tỷ lệ trả lời đạt rubric, lỗi nghiêm trọng, sửa/bác bỏ và CSAT theo nhóm ticket. Đặt ngưỡng go/no-go trước pilot; ví dụ không chấp nhận lỗi nghiêm trọng trong tập nghiệm thu nhưng không coi đó là bảo đảm không có lỗi trong tương lai. Không suy ra tiết kiệm toàn bộ 40.000 phút/tuần từ baseline.'
]}
];
let caseFilterLevel='all',caseFilterDomain='all',activeCase=null;
let caseWork;try{caseWork=JSON.parse(localStorage.getItem('ba-case-work-v1'))||{drafts:{},attempts:{}}}catch{caseWork={drafts:{},attempts:{}}}
const rubricLabels=['Logic & lập luận','Độ đầy đủ','Ưu tiên & đánh đổi','Giao tiếp & kiểm chứng'];
function persistCases(){try{localStorage.setItem('ba-case-work-v1',JSON.stringify(caseWork));return true}catch{toast('Chưa lưu được: bộ nhớ trình duyệt không khả dụng. Hãy tải bài làm xuống.');return false}}
function caseDraft(id){return caseWork.drafts[id]||(caseWork.drafts[id]={answers:Array(7).fill(''),scores:Array(4).fill(''),reflection:'',updated:null})}
function caseLibrary(){let items=caseStudies.filter(c=>(caseFilterLevel==='all'||c.level===caseFilterLevel)&&(caseFilterDomain==='all'||c.domain===caseFilterDomain));return heading('Case study thực hành','Từ vấn đề chưa rõ đến giải pháp có thể kiểm chứng.')+`<div class="case-intro"><div><span class="section-kicker">LEARNING BY DOING</span><h2>Rèn tư duy BA qua từng quyết định.</h2><p>${caseStudies.length} tình huống · 7 bước phân tích · Đáp án tham khảo & rubric tự chấm</p></div><div class="case-intro-icon">${uiIcon('case')}</div></div><div class="case-toolbar"><label>Cấp độ<select id="case-level"><option value="all">Tất cả cấp độ</option>${['Junior','Mid','Senior'].map(v=>`<option ${caseFilterLevel===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Lĩnh vực<select id="case-domain"><option value="all">Tất cả lĩnh vực</option>${[...new Set(caseStudies.map(c=>c.domain))].map(v=>`<option ${caseFilterDomain===v?'selected':''}>${v}</option>`).join('')}</select></label><span>${items.length} tình huống · Dữ liệu giả lập để luyện tập</span></div><div class="case-grid">${items.map(c=>{let d=caseWork.drafts[c.id],attempts=caseWork.attempts[c.id]||[],filled=d?d.answers.filter(a=>a.trim()).length:0;return `<article class="case-card" style="--accent:${c.accent}"><div class="case-card-top"><span class="track-icon">${uiIcon(c.icon)}</span><span class="module-level">${c.level} · ${c.minutes} phút</span></div><span class="case-domain">${c.domain}</span><h2>${c.title}</h2><p>${c.summary}</p><div class="case-skill">${c.skill}</div><div class="progress-label"><span>${attempts.length?attempts.length+' lần tự chấm':filled?'Bản nháp · '+filled+'/7 bước':'Sẵn sàng bắt đầu'}</span><b>${filled}/7</b></div>${bar(Math.round(filled/7*100),c.accent)}<button class="primary" data-case-open="${c.id}">${filled?'Tiếp tục phân tích':'Bắt đầu thực hành'}</button></article>`}).join('')||'<p class="empty">Không có tình huống phù hợp.</p>'}</div><section class="panel case-guide"><h3>Cách luyện hiệu quả</h3><p>Đọc dữ kiện, ghi rõ điều chưa biết và tự làm trước khi xem đáp án. Không có duy nhất một lời giải đúng: hãy bảo vệ lựa chọn bằng bằng chứng, tác động và các đánh đổi.</p><p>Đây là bài tập tự biên soạn với số liệu giả lập, không phải hồ sơ dự án có thật hoặc đáp án chính thức của IIBA.</p></section>`}
function caseDetail(){const c=caseStudies.find(c=>c.id===activeCase),d=caseDraft(c.id),attempts=caseWork.attempts[c.id]||[];return `<div class="case-detail"><button class="case-back" id="case-back">Case study / ${c.domain}</button><div class="case-detail-head"><span class="case-domain">${c.level} · ${c.minutes} phút · ${c.skill}</span><h1>${c.title}</h1><p>Đọc đề, tự phân tích và đối chiếu các quyết định của bạn.</p></div><div class="case-workspace"><div><section class="panel case-brief"><h2>Bối cảnh</h2><p>${c.context}</p><h3>Dữ kiện được cung cấp</h3><ul>${c.facts.map(f=>`<li>${f}</li>`).join('')}</ul><div class="case-twist"><b>Điểm khó của tình huống</b><p>${c.twist}</p></div><p class="metadata">Toàn bộ tên tổ chức, số liệu và chính sách trong đề là giả lập. Không tự bổ sung giả định như dữ kiện đã xác nhận.</p></section><section class="case-answer-head"><h2>Bài phân tích của bạn</h2><span id="case-save-state" role="status">${d.updated?'Bản nháp đã lưu trên thiết bị':'Tự động lưu trên thiết bị'}</span></section>${caseSteps.map(([name,prompt],i)=>`<section class="panel case-step" id="case-step-${i}"><h3><span>${String(i+1).padStart(2,'0')}</span>${name}</h3><label for="case-answer-${i}">${prompt}</label><textarea id="case-answer-${i}" data-case-answer="${i}" rows="5" placeholder="Ghi nhận dữ kiện, lập luận và lựa chọn của bạn…">${esc(d.answers[i])}</textarea><details><summary>Gợi ý tiếp cận</summary><p>${i===0?c.hint:i===1?'Đặt câu hỏi mở, xác định người trả lời và bằng chứng cần thu thập. Đừng hỏi chỉ để xác nhận giải pháp đã chọn.':i===2?'Nêu ai sở hữu vấn đề, ai quyết định và ai có thể phát hiện ngoại lệ. Thêm cách xác nhận hiểu biết sau trao đổi.':i===3?'Dùng ID cho yêu cầu; liên kết mỗi Must với vấn đề. Đặt ngưỡng NFR có thể đo và ghi rõ ngưỡng nào chỉ là đề xuất.':i===4?'Mô tả điều kiện trước, hành động và kết quả mong đợi. Bao gồm luồng lỗi và trạng thái biên; tránh chỉ mô tả happy path.':i===5?'Mỗi rủi ro cần một biện pháp cụ thể và người sở hữu; chỉ liệt kê “thiếu thời gian” là chưa đủ.':'Định nghĩa rõ tử số, mẫu số, thời điểm và phạm vi. KPI cải thiện không được che giấu tác động xấu ở chỉ số khác.'}</p></details></section>`).join('')}<section class="panel case-model"><h2>Đối chiếu đáp án tham khảo</h2><p>Hãy lưu lập luận của bạn trước. Các gợi ý dưới đây là một hướng giải, không phải đáp án duy nhất.</p><details id="case-model-details"><summary>Mở hướng giải theo 7 bước</summary>${c.models.map((m,i)=>`<div class="case-model-step"><h3>${i+1}. ${caseSteps[i][0]}</h3><p>${m}</p></div>`).join('')}<div class="callout tip"><b>Câu hỏi phỏng vấn tiếp nối</b><br>Nếu chỉ được triển khai một thay đổi trong hai tuần, bạn chọn gì? Bạn cần thêm bằng chứng nào để thay đổi quyết định của mình?</div></details></section><section class="panel case-rubric"><h2>Rubric tự chấm · 100 điểm</h2><p>Mỗi tiêu chí từ 0–5 điểm, quy đổi trọng số bằng nhau: tổng điểm × 5. Điểm do bạn tự đánh giá, không phải chấm tự động.</p><div class="rubric-anchors"><b>Mốc đánh giá chung</b><span>0: chưa có · 1: chung chung · 2: có ý chính nhưng thiếu chứng cứ · 3: hợp lý, còn thiếu ngoại lệ · 4: đầy đủ, có kiểm chứng · 5: lập luận chặt, nêu rõ đánh đổi và cách đo.</span></div>${rubricLabels.map((n,i)=>`<label class="rubric-row"><span><b>${n}</b><small>${['Bám dữ kiện, phân biệt giả định, kết nối nguyên nhân – giải pháp.','Có stakeholder, rules, NFR, ngoại lệ và rủi ro.','Có lý do ưu tiên, so sánh phương án và phạm vi MVP.','Yêu cầu rõ, AC kiểm chứng được, KPI có định nghĩa.'][i]}</small></span><select data-case-score="${i}" aria-label="Điểm ${n}"><option value="">Chọn điểm</option>${[0,1,2,3,4,5].map(v=>`<option value="${v}" ${String(d.scores[i])===String(v)?'selected':''}>${v} / 5</option>`).join('')}</select></label>`).join('')}<label class="case-reflection" for="case-reflection">Điểm cần cải thiện ở lần sau<textarea id="case-reflection" rows="3" placeholder="Tôi đã bỏ sót điều gì? Lập luận nào cần thêm bằng chứng?">${esc(d.reflection||'')}</textarea></label><div class="case-submit-row"><span id="case-total">${d.scores.every(v=>v!=='')?d.scores.reduce((n,v)=>n+Number(v),0)*5+' / 100':'Chọn đủ 4 tiêu chí để tính điểm'}</span><button id="case-submit" class="primary">Lưu lần tự chấm</button><button id="case-export">Tải bài làm .md</button></div><p id="case-validation" role="status"></p></section><section class="panel"><h2 class="case-history-title">Lịch sử thực hành <span>${attempts.length} lần</span></h2>${attempts.length?attempts.slice().reverse().map((a,i)=>`<details class="case-history"><summary>Lần ${attempts.length-i} · ${new Date(a.at).toLocaleString('vi-VN',{timeZone:'Asia/Saigon'})} · ${a.total}/100</summary><p class="metadata">Tự chấm: ${a.scores.join(' / ')} (mỗi tiêu chí tối đa 5)</p>${a.answers.map((x,j)=>`<h4>${caseSteps[j][0]}</h4><p class="case-saved-text">${esc(x)}</p>`).join('')}<p class="case-saved-text">Ghi chú: ${esc(a.reflection||'Chưa ghi chú')}</p></details>`).join(''):'<p class="metadata">Chưa có lần tự chấm nào. Bản nháp vẫn được giữ khi bạn rời trang.</p>'}</section><section class="panel case-sources"><h3>Nguồn tham khảo phương pháp</h3><p>Tham khảo cách phân tích yêu cầu, cộng tác với stakeholder và kiểm tra chất lượng user story. Các nguồn không phải tác giả của tình huống giả lập này.</p><a href="https://www.iiba.org/knowledgehub/the-business-analysis-standard/4-implementing-business-analysis/4-4-understanding-requirements-and-designs/" target="_blank" rel="noopener noreferrer">IIBA · Understanding Requirements and Designs</a><a href="https://www.iiba.org/professional-development/knowledge-centre/articles/engaging-stakeholders-in-elicitation-and-collaboration/" target="_blank" rel="noopener noreferrer">IIBA · Engaging Stakeholders</a><a href="https://agilealliance.org/glossary/invest/" target="_blank" rel="noopener noreferrer">Agile Alliance · INVEST</a></section></div><nav class="case-outline panel" aria-label="Các bước giải case"><h3>Khung phân tích</h3>${caseSteps.map(([n],i)=>`<a href="#case-step-${i}"><span>${i+1}</span>${n}</a>`).join('')}<div class="case-outline-note">Bài làm được lưu trong trình duyệt. Tải bản .md để giữ bản sao.</div></nav></div></div>`}
function casePage(){return activeCase?caseDetail():caseLibrary()}
document.addEventListener('change',e=>{if(e.target.id==='case-level'||e.target.id==='case-domain'){if(e.target.id==='case-level')caseFilterLevel=e.target.value;else caseFilterDomain=e.target.value;render()}if(e.target.matches('[data-case-score]')&&activeCase){let d=caseDraft(activeCase);d.scores[+e.target.dataset.caseScore]=e.target.value;persistCases();document.querySelector('#case-total').textContent=d.scores.every(v=>v!=='')?d.scores.reduce((n,v)=>n+Number(v),0)*5+' / 100':'Chọn đủ 4 tiêu chí để tính điểm'}});
document.addEventListener('input',e=>{if(!activeCase||!e.target.matches('[data-case-answer],#case-reflection'))return;let d=caseDraft(activeCase);if(e.target.dataset.caseAnswer!==undefined)d.answers[+e.target.dataset.caseAnswer]=e.target.value;else d.reflection=e.target.value;d.updated=new Date().toISOString();let ok=persistCases();const note=document.querySelector('#case-save-state');if(note)note.textContent=ok?'Đã lưu bản nháp trên thiết bị':'Chưa lưu được — hãy tải bài làm';});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.caseOpen){activeCase=b.dataset.caseOpen;go('Case study')}if(b.id==='case-back'){activeCase=null;render();window.scrollTo(0,0)}if(b.id==='case-submit'){let d=caseDraft(activeCase),missing=d.answers.findIndex(x=>!x.trim());if(missing>=0){document.querySelector('#case-validation').textContent='Hãy viết câu trả lời cho đủ 7 bước trước khi lưu lần tự chấm. Bản nháp vẫn được lưu.';document.querySelector('#case-answer-'+missing).focus();return}if(d.scores.some(v=>v==='')){document.querySelector('#case-validation').textContent='Hãy chọn điểm cho đủ 4 tiêu chí.';return}let a={at:new Date().toISOString(),answers:[...d.answers],scores:[...d.scores],reflection:d.reflection,total:d.scores.reduce((n,v)=>n+Number(v),0)*5};(caseWork.attempts[activeCase]||(caseWork.attempts[activeCase]=[])).push(a);if(persistCases()){toast('Đã lưu lần tự chấm. Bạn có thể so sánh ở lịch sử.');render()}}if(b.id==='case-export'){const c=caseStudies.find(c=>c.id===activeCase),d=caseDraft(activeCase);let content='# '+c.title+'\n\nBài tập giả lập — Bài làm cá nhân\n\n'+caseSteps.map(([n],i)=>'## '+(i+1)+'. '+n+'\n\n'+(d.answers[i]||'(Chưa trả lời)')).join('\n\n')+'\n\n## Tự chấm\n\n'+rubricLabels.map((n,i)=>n+': '+(d.scores[i]===''?'chưa chấm':d.scores[i]+'/5')).join('\n')+'\n\n## Ghi chú cải thiện\n\n'+d.reflection;let u=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='BA-case-'+activeCase+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}});
